### 3.3 Module `stripe-setup.ts` - Creation Automatique des Plans Stripe

```typescript
// scripts/lib/stripe-setup.ts
import Stripe from 'stripe';

interface StripePlanConfig {
  name: string;
  description: string;
  monthlyPrice: number;  // en cents
  yearlyPrice: number;   // en cents
  currency: string;
}

const DEFAULT_PLANS: StripePlanConfig[] = [
  {
    name: 'Pro',
    description: 'Ideal for growing teams with advanced collaboration needs',
    monthlyPrice: 4900,  // $49
    yearlyPrice: 40000,  // $400
    currency: 'usd'
  },
  {
    name: 'Ultra', 
    description: 'Enterprise-grade solution for large teams',
    monthlyPrice: 10000, // $100
    yearlyPrice: 100000, // $1000
    currency: 'usd'
  }
];

async function createStripeProducts(stripe: Stripe, appName: string) {
  const results: Record<string, string> = {};

  for (const plan of DEFAULT_PLANS) {
    // 1. Creer le produit
    const product = await stripe.products.create({
      name: `${appName} ${plan.name}`,
      description: plan.description,
    });

    // 2. Creer le prix mensuel
    const monthlyPrice = await stripe.prices.create({
      product: product.id,
      unit_amount: plan.monthlyPrice,
      currency: plan.currency,
      recurring: { interval: 'month' },
      lookup_key: `${appName.toLowerCase()}_${plan.name.toLowerCase()}_monthly`,
    });

    // 3. Creer le prix annuel
    const yearlyPrice = await stripe.prices.create({
      product: product.id,
      unit_amount: plan.yearlyPrice,
      currency: plan.currency,
      recurring: { interval: 'year' },
      lookup_key: `${appName.toLowerCase()}_${plan.name.toLowerCase()}_yearly`,
    });

    // Sauvegarder les IDs
    results[`STRIPE_${plan.name.toUpperCase()}_PLAN_ID`] = monthlyPrice.id;
    results[`STRIPE_${plan.name.toUpperCase()}_YEARLY_PLAN_ID`] = yearlyPrice.id;
  }

  return results;
}
```

### 3.4 Module `cleanup.ts` - Nettoyage du Contenu Template

